# === Append to feed.json ===
with open(FEED_PATH, 'r', encoding='utf-8') as f:
    feed = json.load(f)

# Check IDs don't already exist
existing_ids = {item['id'] for item in feed['items']}
for article in [ARTICLE_1, ARTICLE_2]:
    if article['id'] in existing_ids:
        print(f"WARNING: {article['id']} already exists in feed, skipping!")
    else:
        feed['items'].insert(0, article)
        print(f"Added: {article['id']} — {article['title']}")

with open(FEED_PATH, 'w', encoding='utf-8') as f:
    json.dump(feed, f, ensure_ascii=False, indent=2)
print(f"\nFeed now has {len(feed['items'])} items.")

# === Write individual report JSON files ===
os.makedirs(REPORTS_DIR, exist_ok=True)

for article in [ARTICLE_1, ARTICLE_2]:
    report_path = os.path.join(REPORTS_DIR, f"{article['id']}.json")
    with open(report_path, 'w', encoding='utf-8') as f:
        json.dump(article, f, ensure_ascii=False, indent=2)
    print(f"Report written: {report_path}")

print("\nDone!")
